  "basantmukhari": {"swar": "Rishabh, Dhaivat and Nishad Komal. Rest All Shuddha Swaras.", "vs": "Pancham - Shadj", "notes": ["The poorvang takes Bhairav's S r G m; the uttarang takes Bhairavi's P d n S'.", "Unlike Bhairav, Rishabh and Dhaivat are not given andolan.", "Phrases such as r G m P m and G m r r S show its movement.", "Despite the name it is unrelated to Basant; it belongs to Bhairav thaat."], "b": [["Are Man Tu Japle", "Bada khayal", "Ektaal vilambit", "Bhakti ras"], ["Baalam Aaye Mandirwa", "Sadra", "Jhaptal vilambit", "Shringar ras"], ["Neeko Bhayo Bhor", "Madhya laya khayal", "Jhaptal", "Sunrise"], ["Maan Taj De Re Pyare", "Chota khayal", "Teentaal drut", "Jeevan darshan"], ["Aai Suhani Bhor Nayi", "Chota khayal", "Teentaal drut", "Sunrise"], ["Ni Dha Pa Ma Ga Re Sa", "Sargam", "Teentaal drut", ""]], "bn": 21, "v": []},
  "bhatiyar": {"swar": "Both Madhyams, Rishabh Komal. Rest all Shuddha Swaras.", "vs": "Shuddha Madhyam - Shadj", "notes": ["Rishabh and Nishad are used sparingly in the aroh; N D N P D m recalls Mand.", "Shuddha Madhyam is a resting swara in the avroh; tivra Madhyam opens the uttarang.", "Phrases such as S D ; N P ; D m ; P G give its character.", "A vakra raag best learnt from a guru."], "b": [["Aas Jagi Tore Darsan Ki", "Bada khayal", "Ektaal vilambit", "Virah ras"], ["Gajarwa Baje Mandir Ki Dyodhi Par", "Bada khayal", "Ektaal vilambit", "Sunrise"], ["Sudh Bisar Gai Mori", "Sadra", "Jhaptal vilambit", "Virah ras"], ["Narayan Ko Naam Bhaj Le", "Madhya laya khayal", "Jhaptal", "Bhakti ras"], ["Jago Ho Nar Nari Ab To", "Chota khayal", "Teentaal drut", "Sunrise"], ["Sa Dha Pa Dha Ma Pa", "Sargam", "Teentaal drut", ""]], "bn": 17, "v": []},
