  "bihag": {"swar": "Rishabh and Dhaivat Varjya in Aaroh. Both Madhyams. Rest all Shuddha Swaras.", "vs": "Gandhar - Nishad", "notes": ["P M G m G is the raag-vachak phrase.", "Tivra Madhyam is used when aroh phrases or taans begin on it; shuddha Madhyam elsewhere.", "Nishad is prominent; alaap and taans often start from it.", "Rishabh and Dhaivat are not resting swaras and appear mostly in meend.", "Often placed in Kalyan thaat for its tivra Madhyam, though it keeps a Bilawal character."], "b": [["Rajan Ke Raja", "Bada khayal", "Ektaal vilambit", "Guru vandana"], ["Uchat Gai Neendariya", "Sadra", "Jhaptal vilambit", "Virah ras"], ["Kaiso Hai Ye Tero", "Madhya laya khayal", "Jhaptal", "Shri Krishna"], ["Jamuna Pe Baje", "Chota khayal", "Teentaal drut", "Shri Krishna"], ["Balamuwa Bisro Ri", "Chota khayal", "Ektaal drut", "Virah ras"], ["Pa Ga Ma Ga Ni Sa Ma Ga", "Sargam", "Teentaal drut", ""]], "bn": 9, "v": [["Acharya Tanarang", "Jamuna Pe Baje", "Teentaal"], ["Prakash Vishwanath Ringe", "E Mora Re Mora Re", "Teentaal"]]},
  "bihagda": {"swar": "Rishabh Varjya in Aaroh. Both Nishads. Rest all Shuddha Swaras.", "vs": "Gandhar - Shuddha Nishad", "notes": ["Its chalan follows Bihag with a touch of Khamaj.", "Shuddha Nishad in aroh and avroh; komal Nishad only in the avroh, mainly in G m n D P ; G m G.", "Shuddha Madhyam is central and a nyas swara; tivra Madhyam is rare.", "Rishabh and Dhaivat appear as kan, in G (R) S and N (D) P, as in Bihag."], "b": [["Kaise Dharu Dheer Re", "Bada khayal", "Ektaal vilambit", "Virah ras"], ["Baje Mori Payal Jhananana Ri", "Chota khayal", "Teentaal drut", "Shringar ras"], ["Murali Me Meethi Taan Sunaye", "Chota khayal", "Teentaal drut", "Shri Krishna"], ["Dir Dir Tanan Tanan", "Tarana", "Teentaal drut", "For dance"], ["Ga Ma Pa Dha Ni Dha Pa", "Sargam", "Teentaal drut", ""]], "bn": 8, "v": []},
